create extension if not exists postgis;
create extension if not exists pgcrypto;

create type public.app_role as enum ('SUPER_ADMIN','NATIONAL_ADMIN','DEPARTMENT_ADMIN','PROJECT_OFFICER','DISTRICT_OFFICER','FIELD_OFFICER','REVIEWER','VIEWER');
create type public.case_status as enum ('DRAFT','SUBMITTED','UNDER_REVIEW','IN_PROGRESS','AWAITING_APPROVAL','APPROVED','COMPENSATION_PENDING','COMPENSATION_COMPLETED','POSSESSION_PENDING','POSSESSION_COMPLETED','RR_PENDING','CLOSED','REJECTED','ON_HOLD');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, department_id uuid, district_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.roles (id uuid primary key default gen_random_uuid(), code public.app_role unique not null, name text not null);
create table public.user_roles (user_id uuid references public.profiles(id) on delete cascade, role_id uuid references public.roles(id) on delete cascade, primary key(user_id, role_id));
create table public.departments (id uuid primary key default gen_random_uuid(), name text unique not null, code text unique not null);
create table public.states (id uuid primary key default gen_random_uuid(), name text unique not null, code text unique not null);
create table public.districts (id uuid primary key default gen_random_uuid(), state_id uuid references public.states(id), name text not null);
create table public.projects (id uuid primary key default gen_random_uuid(), project_id text unique not null, name text not null, department_id uuid references public.departments(id), project_type text not null, state_id uuid references public.states(id), district_id uuid references public.districts(id), description text, status text not null default 'DRAFT', start_date date, target_completion_date date, geometry geometry(Geometry,4326), created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index projects_geometry_gist on public.projects using gist(geometry);
create table public.project_members (project_id uuid references public.projects(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role public.app_role not null, primary key(project_id,user_id));
create table public.parcels (id uuid primary key default gen_random_uuid(), parcel_id text unique not null, state_id uuid references public.states(id), district_id uuid references public.districts(id), tehsil text, village text, survey_number text, total_area numeric(14,4) not null, geometry geometry(Polygon,4326) not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index parcels_geometry_gist on public.parcels using gist(geometry);
create table public.project_parcels (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects(id) on delete cascade, parcel_id uuid references public.parcels(id), required_area numeric(14,4) not null, affected_geometry geometry(Polygon,4326), created_at timestamptz not null default now(), unique(project_id,parcel_id));
create index project_parcels_geometry_gist on public.project_parcels using gist(affected_geometry);
create table public.acquisition_cases (id uuid primary key default gen_random_uuid(), case_id text unique not null, project_id uuid references public.projects(id), project_parcel_id uuid references public.project_parcels(id), land_owner_reference text, status public.case_status not null default 'DRAFT', priority text not null default 'MEDIUM', risk_level text not null default 'LOW', current_stage text, assigned_officer uuid references public.profiles(id), acquisition_purpose text, external_reference_summary jsonb not null default '[]', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workflow_templates (id uuid primary key default gen_random_uuid(), name text not null, version integer not null default 1, active boolean not null default true, created_at timestamptz not null default now());
create table public.workflow_stages (id uuid primary key default gen_random_uuid(), template_id uuid references public.workflow_templates(id) on delete cascade, stage_name text not null, sequence integer not null, responsible_role public.app_role not null, required_documents jsonb not null default '[]', approval_required boolean not null default false, escalation_rules jsonb not null default '{}', unique(template_id,sequence));
create type public.task_status as enum ('NOT_STARTED','IN_PROGRESS','COMPLETED','BLOCKED','REJECTED','OVERDUE');
create table public.case_workflow_instances (id uuid primary key default gen_random_uuid(), case_id uuid references public.acquisition_cases(id) on delete cascade, template_id uuid references public.workflow_templates(id), overall_progress numeric(5,2) not null default 0, created_at timestamptz not null default now());
create table public.case_workflow_tasks (id uuid primary key default gen_random_uuid(), instance_id uuid references public.case_workflow_instances(id) on delete cascade, stage_id uuid references public.workflow_stages(id), assigned_user uuid references public.profiles(id), status public.task_status not null default 'NOT_STARTED', started_at timestamptz, due_at timestamptz, completed_at timestamptz, remarks text);
create table public.documents (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects(id), case_id uuid references public.acquisition_cases(id), parcel_id uuid references public.parcels(id), workflow_stage_id uuid references public.workflow_stages(id), document_type text not null, canonical_name text not null, description text, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.document_versions (id uuid primary key default gen_random_uuid(), document_id uuid references public.documents(id) on delete cascade, version_number integer not null, file_name text not null, mime_type text not null, file_size bigint not null, storage_object_key text not null unique, checksum text, uploaded_by uuid references public.profiles(id), change_description text, status text not null default 'CURRENT', uploaded_at timestamptz not null default now(), unique(document_id,version_number));
create table public.compensation_records (id uuid primary key default gen_random_uuid(), case_id uuid unique references public.acquisition_cases(id) on delete cascade, eligible_amount numeric(16,2) not null default 0, award_amount numeric(16,2) not null default 0, paid_amount numeric(16,2) not null default 0, payment_status text not null default 'NOT_STARTED', beneficiary_reference text, payment_reference text, payment_date date, external_payment_system text, last_synchronized_at timestamptz);
create table public.rr_records (id uuid primary key default gen_random_uuid(), case_id uuid unique references public.acquisition_cases(id) on delete cascade, affected_family_reference text, eligible boolean, entitlement_type text, status text not null default 'NOT_STARTED', assigned_officer uuid references public.profiles(id), target_date date, completion_date date, remarks text);
create table public.possession_records (id uuid primary key default gen_random_uuid(), case_id uuid unique references public.acquisition_cases(id) on delete cascade, status text not null default 'PENDING', possession_date date, remarks text);
create table public.external_systems (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, adapter_key text not null, is_mock boolean not null default true);
create table public.external_references (id uuid primary key default gen_random_uuid(), case_id uuid references public.acquisition_cases(id) on delete cascade, system_id uuid references public.external_systems(id), external_case_id text, external_reference text, last_synced_at timestamptz);
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete cascade, type text not null, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_user_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, occurred_at timestamptz not null default now(), ip_address inet, metadata jsonb not null default '{}');

create or replace function public.has_role(required_role public.app_role) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id where ur.user_id = auth.uid() and r.code = required_role); $$;
alter table public.projects enable row level security; alter table public.acquisition_cases enable row level security; alter table public.documents enable row level security; alter table public.document_versions enable row level security; alter table public.audit_logs enable row level security;
create policy projects_read_authorized on public.projects for select using (public.has_role('SUPER_ADMIN') or public.has_role('NATIONAL_ADMIN') or exists(select 1 from public.project_members pm where pm.project_id = id and pm.user_id = auth.uid()));
create policy cases_read_authorized on public.acquisition_cases for select using (public.has_role('SUPER_ADMIN') or public.has_role('NATIONAL_ADMIN') or exists(select 1 from public.project_members pm join public.projects p on p.id = pm.project_id where p.id = project_id and pm.user_id = auth.uid()));
create policy cases_update_assigned on public.acquisition_cases for update using (public.has_role('SUPER_ADMIN') or public.has_role('NATIONAL_ADMIN') or assigned_officer = auth.uid());
create policy documents_read_authorized on public.documents for select using (public.has_role('SUPER_ADMIN') or public.has_role('NATIONAL_ADMIN') or exists(select 1 from public.acquisition_cases c join public.project_members pm on pm.project_id = c.project_id where c.id = case_id and pm.user_id = auth.uid()));
create policy document_versions_read_authorized on public.document_versions for select using (exists(select 1 from public.documents d where d.id = document_id));
create policy audit_admin_read on public.audit_logs for select using (public.has_role('SUPER_ADMIN') or public.has_role('NATIONAL_ADMIN'));
